<script setup>
import {ref,onMounted,watch} from 'vue';import {request} from '@/integration/service';
const props=defineProps({id:[String,Number],type:String,authorId:[String,Number]});const expanded=ref(true),rows=ref([]),name=ref(''),content=ref(''),website=ref(''),busy=ref(false),feedback=ref(''),enabled=ref(true);
async function load(){if(!props.id)return;try{rows.value=await request('/api/public/posts/'+encodeURIComponent(props.id)+'/comments');enabled.value=(await request('/api/site')).commentsEnabled;}catch(e){feedback.value=e.message;}}
async function submit(){busy.value=true;try{const r=await request('/api/public/posts/'+encodeURIComponent(props.id)+'/comments','POST',{name:name.value,content:content.value,website:website.value});feedback.value=r.message;content.value='';}catch(e){feedback.value=e.message;}finally{busy.value=false;}}
defineExpose({toggleExpand(){expanded.value=true;}});onMounted(load);watch(()=>props.id,load);
</script>
<template><section class="comment source-comments"><header @click="expanded=!expanded">评论 {{rows.length}} <small>先审核，后展示</small></header><div v-if="expanded"><article v-for="c in rows" :key="c.id" class="reviewed-comment"><el-avatar>{{c.name.slice(0,1)}}</el-avatar><div><strong>{{c.name}}</strong><small> · 未验证昵称 · {{c.created.slice(0,10)}}</small><p>{{c.content}}</p></div></article><p v-if="!rows.length" class="muted">还没有公开的评论。</p><form v-if="enabled" id="comment-form" @submit.prevent="submit"><label>昵称<input name="name" v-model="name" required maxlength="40" placeholder="怎么称呼你？"></label><label>评论内容<textarea name="content" v-model="content" required minlength="2" maxlength="2000" rows="4" placeholder="写下你的想法，审核通过后才会公开。"></textarea></label><input class="honey" tabindex="-1" aria-hidden="true" name="website" v-model="website"><div class="submit-line"><small>昵称为自由填写，请勿留下私人联系方式。</small><el-button type="primary" native-type="submit" :loading="busy">提交并等待审核</el-button></div></form><p v-else>评论暂时关闭。</p><p class="comment-feedback" role="status">{{feedback}}</p></div></section></template>
<style scoped>.source-comments{padding:20px;color:var(--font-color)}header{font-size:20px;margin-bottom:25px;cursor:pointer}small{font-size:11px;opacity:.7}header small{float:right}.reviewed-comment{display:flex;gap:15px;padding:20px 0;border-bottom:1px solid #8883}.reviewed-comment>div{min-width:0;flex:1}.reviewed-comment p{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px 0;line-height:1.8}form{margin-top:25px}label{display:block;font-size:13px;margin-bottom:18px}input,textarea{display:block;width:100%;box-sizing:border-box;margin-top:8px;padding:12px;border:1px solid #8884;background:var(--el-bg-color);border-radius:5px;color:inherit;font:inherit}input[name=name]{max-width:280px}.submit-line{display:flex;align-items:center;justify-content:space-between;gap:15px}.honey{display:none}.comment-feedback{padding-top:15px;color:var(--el-color-primary)}@media(max-width:600px){.submit-line{align-items:start;flex-direction:column}.source-comments{padding:10px}header small{float:none;display:block;margin-top:10px}}</style>
